"""Database models for api_academia.

Defines the SQLAlchemy ORM models representing domain entities.
"""

from datetime import datetime
from typing import Dict, Any
from .database import db


class Treino(db.Model):
    """SQLAlchemy model representing a workout routine generated by AI."""

    __tablename__ = 'treinos'

    id = db.Column(db.Integer, primary_key=True, autoincrement=True)
    objetivo = db.Column(db.String(255), nullable=False)
    nivel = db.Column(db.String(50), nullable=False, default='iniciante')
    treino_gerado = db.Column(db.Text, nullable=False)
    criado_em = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)

    def to_dict(self) -> Dict[str, Any]:
        """Converts model instance into a dictionary representation."""
        return {
            "id": self.id,
            "objetivo": self.objetivo,
            "nivel": self.nivel,
            "treino_gerado": self.treino_gerado,
            "criado_em": self.criado_em.strftime("%Y-%m-%dT%H:%M:%SZ") if self.criado_em else None
        }

    def __repr__(self) -> str:
        return f"<Treino id={self.id} objetivo='{self.objetivo}' nivel='{self.nivel}'>"
